// pages/dashboard/profile.jsx
import DashboardLayout from "../../components/DashboardLayout";
import { useState, useEffect } from "react";
import { BASE_URL, getAuthHeader } from "../../utils/api";
import { User, Mail, Phone, Lock } from "lucide-react";

export default function Profile() {
  const [user, setUser] = useState({ name: "", email: "", phone: "" });
  const [passwords, setPasswords] = useState({ current: "", new: "" });
  const [loading, setLoading] = useState(true);
  const [message, setMessage] = useState("");

  useEffect(() => {
    async function fetchProfile() {
      try {
        const res = await fetch(`${BASE_URL}/api/user/profile`, {
          headers: { ...getAuthHeader() },
        });
        const data = await res.json();
        setUser(data);
      } catch (err) {
        console.error(err);
      } finally {
        setLoading(false);
      }
    }
    fetchProfile();
  }, []);

  const handleSave = async () => {
    try {
      const res = await fetch(`${BASE_URL}/api/user/profile`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          ...getAuthHeader(),
        },
        body: JSON.stringify(user),
      });

      if (!res.ok) throw new Error();
      setMessage("Profile updated successfully");
    } catch {
      setMessage("Error updating profile");
    }
  };

  const handlePasswordChange = async () => {
    try {
      const res = await fetch(`${BASE_URL}/api/user/change-password`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          ...getAuthHeader(),
        },
        body: JSON.stringify(passwords),
      });

      if (!res.ok) throw new Error();
      setMessage("Password changed successfully");
      setPasswords({ current: "", new: "" });
    } catch {
      setMessage("Error changing password");
    }
  };

  if (loading) {
    return (
      <DashboardLayout>
        <div className="text-center mt-20 text-zinc-400">
          Loading profile...
        </div>
      </DashboardLayout>
    );
  }

  return (
    <DashboardLayout>
      {/* MATCH DASHBOARD BACKGROUND */}
      <div className="min-h-screen bg-zinc-950 text-white p-6 md:p-10">
        <div className="max-w-2xl mx-auto space-y-10">

          <h2 className="text-2xl font-bold">My Profile</h2>

          {message && (
            <div className="text-emerald-400">{message}</div>
          )}

          {/* PROFILE (NO BOX) */}
          <div className="space-y-4">

            <div>
              <label className="text-sm text-zinc-400">Name</label>
              <div className="flex items-center bg-zinc-800 rounded-xl px-3 mt-1">
                <User className="w-4 mr-2" />
                <input
                  className="bg-transparent w-full p-3 outline-none"
                  value={user.name}
                  onChange={(e) => setUser({ ...user, name: e.target.value })}
                />
              </div>
            </div>

            <div>
              <label className="text-sm text-zinc-400">Email</label>
              <div className="flex items-center bg-zinc-800 rounded-xl px-3 mt-1">
                <Mail className="w-4 mr-2" />
                <input
                  className="bg-transparent w-full p-3 outline-none"
                  value={user.email}
                  onChange={(e) => setUser({ ...user, email: e.target.value })}
                />
              </div>
            </div>

            <div>
              <label className="text-sm text-zinc-400">Phone</label>
              <div className="flex items-center bg-zinc-800 rounded-xl px-3 mt-1">
                <Phone className="w-4 mr-2" />
                <input
                  className="bg-transparent w-full p-3 outline-none"
                  value={user.phone}
                  onChange={(e) => setUser({ ...user, phone: e.target.value })}
                />
              </div>
            </div>

            <button
              onClick={handleSave}
              className="w-full bg-emerald-600 py-3 rounded-xl mt-4"
            >
              Save Changes
            </button>
          </div>

          {/* PASSWORD (NO BOX) */}
          <div className="space-y-4">
            <h3 className="text-lg font-semibold">Change Password</h3>

            <div>
              <label className="text-sm text-zinc-400">Current Password</label>
              <div className="flex items-center bg-zinc-800 rounded-xl px-3 mt-1">
                <Lock className="w-4 mr-2" />
                <input
                  type="password"
                  className="bg-transparent w-full p-3 outline-none"
                  value={passwords.current}
                  onChange={(e) =>
                    setPasswords({ ...passwords, current: e.target.value })
                  }
                />
              </div>
            </div>

            <div>
              <label className="text-sm text-zinc-400">New Password</label>
              <div className="flex items-center bg-zinc-800 rounded-xl px-3 mt-1">
                <Lock className="w-4 mr-2" />
                <input
                  type="password"
                  className="bg-transparent w-full p-3 outline-none"
                  value={passwords.new}
                  onChange={(e) =>
                    setPasswords({ ...passwords, new: e.target.value })
                  }
                />
              </div>
            </div>

            <button
              onClick={handlePasswordChange}
              className="w-full bg-emerald-600 py-3 rounded-xl"
            >
              Update Password
            </button>
          </div>

        </div>
      </div>
    </DashboardLayout>
  );
}
